BEGIN TRANSACTION;
CREATE TABLE "CitesTable" (
	"id"	INTEGER NOT NULL,
	"cityNameEN"	TEXT,
	"cityNameAR"	TEXT,
	"lat"	TEXT,
	"lng"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE "Prayer" (
	"fajerTime"	TEXT NOT NULL,
	"sunRiseTime"	TEXT NOT NULL,
	"duhirTime"	TEXT NOT NULL,
	"aserTime"	TEXT NOT NULL,
	"mugribTime"	TEXT NOT NULL,
	"eshaTime"	TEXT NOT NULL,
	"dayy"	INTEGER NOT NULL,
	"monthh"	INTEGER NOT NULL,
	"cityId"	INTEGER NOT NULL,
	"prayerId"	INTEGER NOT NULL,
	PRIMARY KEY("prayerId")
);
CREATE TABLE "Sounds" (
	"id"	INTEGER NOT NULL UNIQUE,
	"soundName"	TEXT NOT NULL,
	"soundFileName"	TEXT NOT NULL,
	"soundUri"	TEXT NOT NULL,
	"isDefault"	INTEGER NOT NULL,
	"soundSize"	INTEGER NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
DELETE FROM "sqlite_sequence";
COMMIT;
